1	import { AdditiveBlending, ShaderMaterial } from 'three'
2	
3	/**
4	 * The material every luminous point layer in the deck uses.
5	 *
6	 * Points, not billboarded quads: a point sprite always faces the camera and
7	 * the whole layer is one draw call, which is what keeps 147 pulsing agents and
8	 * a hundred finding markers inside the frame budget. Size and brightness are
9	 * per-point attributes, so a scene animates a typed array rather than a scene
10	 * graph.
11	 * @returns A new additive point material; each layer owns its own instance.
12	 */
13	export function createGlowMaterial(): ShaderMaterial {
14	  return new ShaderMaterial({
15	    transparent: true,
16	    depthWrite: false,
17	    blending: AdditiveBlending,
18	    uniforms: {},
19	    vertexShader: /* glsl */`
20	      attribute float aSize;
21	      attribute vec3 aColor;
22	      attribute float aGain;
23	      varying vec3 vColor;
24	      varying float vGain;
25	      void main() {
26	        vColor = aColor;
27	        vGain = aGain;
28	        vec4 mv = modelViewMatrix * vec4(position, 1.0);
29	        gl_PointSize = aSize * (320.0 / max(-mv.z, 0.001));
30	        gl_Position = projectionMatrix * mv;
31	      }
32	    `,
33	    fragmentShader: /* glsl */`
34	      varying vec3 vColor;
35	      varying float vGain;
36	      void main() {
37	        float d = length(gl_PointCoord - vec2(0.5));
38	        if (d > 0.5) discard;
39	        float core = smoothstep(0.5, 0.06, d);
40	        float halo = smoothstep(0.5, 0.0, d) * 0.45;
41	        gl_FragColor = vec4(vColor * (core + halo), (core + halo) * vGain);
42	      }
43	    `,
44	  })
45	}
