/** TEMPORARY frame-time probe; removed before commit. */
function FrameProbe(): ReactNode {
  const probe = useRef({ deltas: new Float64Array(120), cursor: 0, last: 0 })
  useFrame(() => {
    const now = performance.now()
    const state = probe.current
    if (state.last !== 0) {
      state.deltas[state.cursor % state.deltas.length] = now - state.last
      state.cursor += 1
    }
    state.last = now
    if (state.cursor > 0 && state.cursor % 30 === 0) {
      const sorted = [...state.deltas].filter(value => value > 0).sort((a, b) => a - b)
      const median = sorted[Math.floor(sorted.length / 2)] ?? 0
      ;(window as unknown as { __deckFrameMs?: number }).__deckFrameMs = median
      // eslint-disable-next-line no-console
      console.log(`[deck] enterprise frame median ${median.toFixed(2)} ms over ${sorted.length}`)
    }
  })
  return null
}

