 * anchored in 3D, so they carry no background box large enough to hide the
 * scene behind them.
 */

.division {
  white-space: nowrap;
  text-align: center;
  transform: translateY(-7px);
  padding: 2px 2px 3px;
  text-shadow: 0 0 14px rgba(0, 0, 0, 0.95), 0 1px 3px rgba(0, 0, 0, 0.9);
  transition: opacity 260ms ease;
}

