    ring.setColorAt(slot, SCRATCH_COLOR)
    beam.setColorAt(slot, SCRATCH_COLOR)
  }
  if (ring.instanceColor !== null) ring.instanceColor.needsUpdate = true
  if (beam.instanceColor !== null) beam.instanceColor.needsUpdate = true
}, [])

