'use client'

import { useFrame } from '@react-three/fiber'
import { useMemo, useRef, type ReactNode } from 'react'
import type { Roster } from '@/deck/contract'
import { layoutRoster } from '@/deck/layout-enterprise'
import { Stage } from '@/components/three/Stage'
import { AgentGraph } from './AgentGraph'
import { CameraRig } from './CameraRig'
import { CertificateBursts } from './CertificateBursts'
import { Constellations } from './Constellations'
import { GraphEdges } from './GraphEdges'

/** TEMPORARY frame-time probe; removed before commit. */
function FrameProbe(): ReactNode {
  const probe = useRef({ deltas: new Float64Array(120), cursor: 0, last: 0 })
  useFrame(() => {
    const now = performance.now()
    const state = probe.current
    if (state.last !== 0) {
      state.deltas[state.cursor % state.deltas.length] = now - state.last
      state.cursor += 1
    }
    state.last = now
    if (state.cursor > 0 && state.cursor % 30 === 0) {
      const sorted = [...state.deltas].filter(value => value > 0).sort((a, b) => a - b)
      const median = sorted[Math.floor(sorted.length / 2)] ?? 0
      ;(window as unknown as { __deckFrameMs?: number }).__deckFrameMs = median
      // eslint-disable-next-line no-console
      console.log(`[deck] enterprise frame median ${median.toFixed(2)} ms over ${sorted.length}`)
    }
  })
  return null
}

/**
 * The enterprise scene: ten constellations, their agents, the relationships
 * between them, and the traffic the run puts on those relationships.
 * @param props - The roster to draw.
 * @returns The canvas and its contents.
 */
export function EnterpriseStage({ roster }: { roster: Roster }): ReactNode {
  const layout = useMemo(() => layoutRoster(roster), [roster])

  return (
    <Stage camera={{ position: [0, layout.extent * 0.26, layout.extent * 2.2], fov: 44 }} fogNear={210} fogFar={720}>
      <Constellations roster={roster} layout={layout} />
      <GraphEdges roster={roster} layout={layout} />
      <AgentGraph roster={roster} layout={layout} />
      <CertificateBursts layout={layout} />
      <CameraRig layout={layout} />
      <FrameProbe />
    </Stage>
  )
}

